  async fetchDevices() {
    return new Promise((resolve, reject) => {
      fetch.fetch({
        url: `${API_BASE_URL}/api/devices`,
        method: 'GET',
        responseType: 'json',
        success: (response) => {
          resolve(response.data)
        },
        fail: (data, code) => {
          console.log('Fetch devices failed:', code)
          reject(new Error(`Failed to fetch devices: ${code}`))
        }
      })
    })
  },

  async fetchSuggestions() {
    return new Promise((resolve, reject) => {
      fetch.fetch({
        url: `${API_BASE_URL}/api/proactive/suggestions`,
        method: 'GET',
        responseType: 'json',
        success: (response) => {
          resolve(response.data)
        },
        fail: (data, code) => {
          console.log('Fetch suggestions failed:', code)
          reject(new Error(`Failed to fetch suggestions: ${code}`))
        }
      })
    })
  },

  async approveSuggestion(suggestionId) {
    return new Promise((resolve, reject) => {
      fetch.fetch({
        url: `${API_BASE_URL}/api/proactive/suggestions/${suggestionId}/action`,
        method: 'POST',
        data: JSON.stringify({ action: 'approved' }),
        responseType: 'json',
        success: (response) => {
          resolve(response.data)
        },
        fail: (data, code) => {
          console.log('Approve suggestion failed:', code)
          reject(new Error(`Failed to approve suggestion: ${code}`))
        }
      })
    })
  },

  async rejectSuggestion(suggestionId) {
    return new Promise((resolve, reject) => {
      fetch.fetch({
        url: `${API_BASE_URL}/api/proactive/suggestions/${suggestionId}/action`,
        method: 'POST',
        data: JSON.stringify({ action: 'rejected' }),
        responseType: 'json',
        success: (response) => {
          resolve(response.data)
        },
        fail: (data, code) => {
          console.log('Reject suggestion failed:', code)
          reject(new Error(`Failed to reject suggestion: ${code}`))
        }
      })
    })
  },

  async toggleDevice(deviceId) {
    return new Promise((resolve, reject) => {
      fetch.fetch({
        url: `${API_BASE_URL}/api/devices/${deviceId}/toggle`,
        method: 'POST',
        responseType: 'json',
        success: (response) => {
          resolve(response.data)
        },
        fail: (data, code) => {
          console.log('Toggle device failed:', code)
          reject(new Error(`Failed to toggle device: ${code}`))
        }
      })
    })
  },

  async syncHealthData(healthData) {
    return new Promise((resolve, reject) => {
      fetch.fetch({
        url: `${API_BASE_URL}/api/health/sync`,
        method: 'POST',
        data: JSON.stringify(healthData),
        responseType: 'json',
        success: (response) => {
          resolve(response.data)
        },
        fail: (data, code) => {
          console.log('Sync health data failed:', code)
          reject(new Error(`Failed to sync health data: ${code}`))
        }
      })
    })
  },

  async saveToLocal(key, value) {
    return new Promise((resolve, reject) => {
      storage.set({
        key: key,
        value: JSON.stringify(value),
        success: () => {
          resolve()
        },
        fail: (data, code) => {
          console.log('Save to local failed:', code)
          reject(new Error(`Failed to save to local: ${code}`))
        }
      })
    })
  },

  async loadFromLocal(key) {
    return new Promise((resolve, reject) => {
      storage.get({
        key: key,
        success: (data) => {
          resolve(data ? JSON.parse(data) : null)
        },
        fail: (data, code) => {
          console.log('Load from local failed:', code)
          reject(new Error(`Failed to load from local: ${code}`))
        }
      })
    })
  }
}

export default api

const utils = {
  formatTime(date) {
    const hours = date.getHours().toString().padStart(2, '0')
    const minutes = date.getMinutes().toString().padStart(2, '0')
    return `${hours}:${minutes}`
  },

  formatDate(date) {
    const year = date.getFullYear()
    const month = (date.getMonth() + 1).toString().padStart(2, '0')
    const day = date.getDate().toString().padStart(2, '0')
    return `${year}-${month}-${day}`
  },

  formatDateTime(date) {
    return `${this.formatDate(date)} ${this.formatTime(date)}`
  },

  getRelativeTime(timestamp) {
    const now = new Date()
    const date = new Date(timestamp)
    const diff = now - date
    const minutes = Math.floor(diff / 60000)
    const hours = Math.floor(diff / 3600000)
    const days = Math.floor(diff / 86400000)

    if (minutes < 1) {
      return '刚刚'
    } else if (minutes < 60) {
      return `${minutes}分钟前`
    } else if (hours < 24) {
      return `${hours}小时前`
    } else if (days < 7) {
      return `${days}天前`
    } else {
      return this.formatDate(date)
    }
  },

  getStressLevel(value) {
    if (value <= 10) {
      return { level: '放松', color: '#22c55e' }
    } else if (value <= 20) {
      return { level: '正常', color: '#3b82f6' }
    } else if (value <= 30) {
      return { level: '中等', color: '#f59e0b' }
    } else {
      return { level: '较高', color: '#ef4444' }
    }
  },

  getHeartRateStatus(value) {
    if (value < 60) {
      return { status: '偏低', color: '#f59e0b' }
    } else if (value <= 100) {
      return { status: '正常', color: '#22c55e' }
    } else {
      return { status: '偏高', color: '#ef4444' }
    }
  },

  getSpo2Status(value) {
    if (value < 90) {
      return { status: '严重偏低', color: '#ef4444' }
    } else if (value < 95) {
      return { status: '偏低', color: '#f59e0b' }
    } else {
      return { status: '正常', color: '#22c55e' }
    }
  },

  generateId() {
    return 'id_' + Math.random().toString(36).substr(2, 9)
  },

  debounce(func, wait) {
    let timeout
    return function executedFunction(...args) {
      const later = () => {
        clearTimeout(timeout)
        func(...args)
      }
      clearTimeout(timeout)
      timeout = setTimeout(later, wait)
    }
  },

  throttle(func, limit) {
    let inThrottle
    return function executedFunction(...args) {
      if (!inThrottle) {
        func(...args)
        inThrottle = true
        setTimeout(() => inThrottle = false, limit)
      }
    }
  }
}

export default utils

